AND ( platform = #{sourcePlatform} OR platform IN ('抖音', '抖音短视频') OR platform IN ('小红书', 'red') OR platform IN ('知乎') OR platform IN ('微博', '新浪微博') OR platform IN ('微信公众号', '微信') OR platform IN ('B站', 'bilibili') OR platform IN ('公开论坛', '论坛', '贴吧', '百度贴吧')
OR platform IN ('新闻媒体', 'news_media', 'public_web', '公开网页', '百度', '人民网', '新华网', '腾讯网', '搜狐', '新浪网', '今日头条', '头条', '百家号', '学校官网', 'school_website', 'college_website', '公开论坛', '论坛', '贴吧', '百度贴吧', '豆瓣')
)

AND ( source_sub_platform = #{sourceSubPlatform} OR source_sub_platform IN ('贴吧', '百度贴吧') OR source_sub_platform IN ('豆瓣') OR source_sub_platform IN ('本地论坛', 'local_bbs')
OR source_sub_platform IS NULL OR source_sub_platform = '' OR source_sub_platform NOT IN ('tieba', '贴吧', '百度贴吧', 'douban', '豆瓣', 'local_forum', 'local_bbs', '本地论坛')
)

AND (
    result_status = #{resultStatus}

        OR clue_id IS NOT NULL

)

AND CAST(info_id AS CHAR) IN ( SELECT latest_info_id FROM ( SELECT SUBSTRING_INDEX( GROUP_CONCAT( CAST(info_id AS CHAR) ORDER BY CASE WHEN publish_time IS NULL THEN 1 ELSE 0 END ASC, publish_time DESC, collect_time DESC, info_id DESC SEPARATOR ',' ), ',', 1 ) AS latest_info_id FROM (
) info WHERE 1 = 1
GROUP BY similar_key ) dedup )

