AND ( title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%') OR matched_subjects LIKE CONCAT('%', #{keyword}, '%') OR matched_keywords LIKE CONCAT('%', #{keyword}, '%') OR matched_negative_words LIKE CONCAT('%', #{keyword}, '%') OR matched_school_terms LIKE CONCAT('%', #{keyword}, '%') OR topic_category LIKE CONCAT('%', #{keyword}, '%') OR topic_reason LIKE CONCAT('%', #{keyword}, '%') )
AND risk_level = #{riskLevel}
AND result_status = #{resultStatus}
AND platform = #{platform}
AND COALESCE(NULLIF(language, ''), 'zh') = #{language}
AND clue_id IS NOT NULL
AND clue_id IS NULL
