SELECT * FROM (
) info WHERE 1 = 1
ORDER BY collect_time DESC, info_id DESC ORDER BY CASE WHEN publish_time IS NULL THEN 1 ELSE 0 END ASC, publish_time DESC, collect_time DESC, info_id DESC ORDER BY sentiment DESC, info_id DESC ORDER BY school_relevance_score DESC, CASE WHEN publish_time IS NULL THEN 1 ELSE 0 END ASC, publish_time DESC, collect_time DESC, info_id DESC ORDER BY CASE WHEN publish_time IS NULL THEN 1 ELSE 0 END ASC, publish_time DESC, collect_time DESC, info_id DESC

SELECT COALESCE(NULLIF(platform, ''), '其它') AS name, COUNT(*) AS value FROM (
) info WHERE 1 = 1
GROUP BY COALESCE(NULLIF(platform, ''), '其它') ORDER BY value DESC

SELECT COALESCE(NULLIF(source_sub_platform, ''), '其它') AS name, COUNT(*) AS value FROM (
) info WHERE 1 = 1
GROUP BY COALESCE(NULLIF(source_sub_platform, ''), '其它') ORDER BY value DESC

